CREATE TABLE pt_currency_rates(id TEXT PRIMARY KEY,currency TEXT NOT NULL,rate_date TEXT NOT NULL,usd_per_unit INTEGER NOT NULL CHECK(usd_per_unit>0),source TEXT NOT NULL,override_reason TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE pt_currency_documents(id TEXT PRIMARY KEY,kind TEXT NOT NULL,target_id TEXT NOT NULL,contact_id TEXT NOT NULL,currency TEXT NOT NULL,foreign_cents INTEGER NOT NULL CHECK(foreign_cents>0),home_cents INTEGER NOT NULL CHECK(home_cents>0),issue_rate_id TEXT NOT NULL REFERENCES pt_currency_rates(id),native_revision TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(kind,target_id));
CREATE TABLE pt_currency_previews(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES pt_currency_documents(id),rate_id TEXT NOT NULL REFERENCES pt_currency_rates(id),as_of TEXT NOT NULL,native_revision TEXT NOT NULL,native_open_cents INTEGER NOT NULL,detail TEXT NOT NULL,created_by TEXT NOT NULL,created_at TEXT NOT NULL);
